// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PhiNFT1155} from "../src/PhiNFT1155.sol";

contract InvMutTest is Test {
    PhiNFT1155 c;
    function setUp() public { c = new PhiNFT1155(); }
    function testRegression_property() public {
        address owner = address(0x1);
        address pendingOwner = address(0x2);
        address attacker = address(0x3);

        vm.prank(address(c.owner()));
        c.transferOwnership(pendingOwner);

        vm.prank(attacker);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("acceptOwnership()"));

        assertTrue(!ok, "acceptOwnership should have reverted for unauthorized caller");
    }
}
